const dictionaries=Object.fromEntries(['en','es','de','ru'].map((code,i)=>[code,new Map(rows.map(r=>[r[0],r[i+1]]))]));
export function translateText(text,lang='tr'){
 if(lang==='tr'||!dictionaries[lang])return text;
 const leading=text.match(/^\s*/)[0],trailing=text.match(/\s*$/)[0],value=text.trim(),dict=dictionaries[lang];if(!value)return text;
 const exact=dict.get(value);if(exact)return leading+exact+trailing;
 const arrow=value.match(/^(.*?)\s*([↗→←])$/);if(arrow&&dict.has(arrow[1]))return leading+dict.get(arrow[1])+' '+arrow[2]+trailing;
 const left=value.match(/^([←☰◈])\s*(.*)$/);if(left&&dict.has(left[2]))return leading+left[1]+' '+dict.get(left[2])+trailing;
 const label=value.match(/^([^:]+):\s*(.*)$/);if(label&&dict.has(label[1]))return leading+dict.get(label[1])+': '+label[2]+trailing;
 if(/^[\d.,]+ oda$/.test(value))return leading+value.replace(/oda$/,({en:'rooms',es:'salas',de:'Räume',ru:'комнат'})[lang])+trailing;
 if(/^\d+\. sayfa$/.test(value))return leading+({en:'Page ',es:'Página ',de:'Seite ',ru:'Страница '})[lang]+value.split('.')[0]+trailing;
 if(/^[\d.,]+ galibiyet$/.test(value))return leading+value.replace(/galibiyet$/,({en:'wins',es:'victorias',de:'Siege',ru:'побед'})[lang])+trailing;
 for(const prefix of ['Ödül','Haykır','Hesap'])if(value.startsWith(prefix+' '))return leading+dict.get(prefix)+value.slice(prefix.length)+trailing;
 if(value.includes(' · ')){const parts=value.split(' · '),out=parts.map(part=>dict.get(part)||part);if(out.some((p,i)=>p!==parts[i]))return leading+out.join(' · ')+trailing;}
 return text;
}
export function initLanguages(){
 let language='tr';try{const saved=localStorage.getItem('agarm_language');if(LANGUAGES[saved])language=saved}catch{}
 const originals=new WeakMap(),attributeSources=new WeakMap();let observer;
 const skip='script,style,textarea,#chat-messages,#leaders,.avatar,.account-top strong,.skin-card small,[data-player],[data-spectate],[data-no-translate],[data-language]';
 function translateNode(node){if(node.nodeType===3){if(!node.parentElement||node.parentElement.closest(skip))return;let entry=originals.get(node);if(!entry||node.nodeValue!==entry.output)entry={source:node.nodeValue};const output=translateText(entry.source,language);entry.output=output;originals.set(node,entry);if(node.nodeValue!==output)node.nodeValue=output;return}if(node.nodeType!==1||node.matches('script,style'))return;
  if(!node.closest(skip))for(const name of ['placeholder','aria-label','title'])if(node.hasAttribute(name)){let entries=attributeSources.get(node)||{},entry=entries[name];const value=node.getAttribute(name);if(!entry||entry.output!==value)entry={source:value};entry.output=translateText(entry.source,language);entries[name]=entry;attributeSources.set(node,entries);if(value!==entry.output)node.setAttribute(name,entry.output);}
  for(const child of node.childNodes)translateNode(child);
 }
 function update(){observer?.disconnect();document.documentElement.lang=language;translateNode(document.body);for(const button of document.querySelectorAll('[data-language]')){button.setAttribute('aria-pressed',String(button.dataset.language===language));button.classList.toggle('selected',button.dataset.language===language)}const footer=document.getElementById('current-language');if(footer)footer.textContent=language.toUpperCase()+' '+LANGUAGES[language].flag;observer?.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});}
 observer=new MutationObserver(records=>{observer.disconnect();for(const record of records){if(record.type==='childList'){for(const node of record.addedNodes)translateNode(node)}else translateNode(record.target)}observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});});
 function choose(code){if(!LANGUAGES[code])return;language=code;try{localStorage.setItem('agarm_language',code)}catch{}update();document.dispatchEvent(new CustomEvent('agarm:language',{detail:{language:code}}));}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-language]');if(b)choose(b.dataset.language)});window.addEventListener('storage',e=>{if(e.key==='agarm_language'&&LANGUAGES[e.newValue]){language=e.newValue;update()}});update();return {get language(){return language},setLanguage:choose,t:text=>translateText(text,language)};
}
